BEGIN;
CREATE TABLE platform.file_batches(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,installation_id text NOT NULL,first_sequence bigint NOT NULL,last_sequence bigint NOT NULL,event_count integer NOT NULL CHECK(event_count BETWEEN 1 AND 1000),content_sha256 text NOT NULL CHECK(content_sha256 ~ '^[0-9a-f]{64}$'),received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,batch_id));
CREATE TABLE platform.file_events(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),event_id uuid NOT NULL,batch_id uuid NOT NULL,endpoint_id uuid NOT NULL,agent_id uuid NOT NULL,file_entity_id text NOT NULL,event_type text NOT NULL CHECK(event_type IN('created','modified','deleted','renamed','moved','metadata_changed','opened','closed')),sequence bigint NOT NULL CHECK(sequence>0),observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),ingested_at timestamptz NOT NULL DEFAULT now(),schema_version text NOT NULL,normalization_version text NOT NULL,collector_type text NOT NULL,collector_version text NOT NULL,source_event_id text,raw_sha256 text,trace_id text,data_quality_flags text[] NOT NULL DEFAULT '{}',late boolean NOT NULL DEFAULT false,event_data jsonb NOT NULL,PRIMARY KEY(tenant_id,event_id),UNIQUE(tenant_id,endpoint_id,agent_id,sequence),FOREIGN KEY(tenant_id,batch_id) REFERENCES platform.file_batches(tenant_id,batch_id));
CREATE INDEX file_events_timeline ON platform.file_events(tenant_id,endpoint_id,observed_at DESC,event_id DESC);
CREATE INDEX file_events_entity ON platform.file_events(tenant_id,endpoint_id,file_entity_id,observed_at,event_id);
CREATE INDEX file_events_process ON platform.file_events(tenant_id,endpoint_id,((event_data#>>'{process,processEntityId}')),observed_at DESC);
CREATE TABLE platform.file_entities(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,file_entity_id text NOT NULL,native_identity jsonb NOT NULL,current_path text NOT NULL,previous_paths text[] NOT NULL DEFAULT '{}',first_observed timestamptz NOT NULL,last_observed timestamptz NOT NULL,created_at timestamptz,deleted_at timestamptz,state text NOT NULL,metadata jsonb NOT NULL,hash_metadata jsonb NOT NULL,latest_process jsonb,user_name text,source_confidence text NOT NULL,latest_event_id uuid NOT NULL,data_quality_flags text[] NOT NULL DEFAULT '{}',collector_type text NOT NULL,collector_version text NOT NULL,PRIMARY KEY(tenant_id,endpoint_id,file_entity_id));
CREATE INDEX file_entities_path ON platform.file_entities(tenant_id,endpoint_id,current_path);
CREATE INDEX file_entities_hash ON platform.file_entities(tenant_id,((hash_metadata->>'sha256')));
CREATE TABLE platform.file_telemetry_health(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,enabled boolean NOT NULL,collector_type text NOT NULL,collector_version text NOT NULL,last_event_at timestamptz,queue_depth bigint NOT NULL DEFAULT 0,oldest_queued_seconds bigint NOT NULL DEFAULT 0,dropped_events bigint NOT NULL DEFAULT 0,excluded_events bigint NOT NULL DEFAULT 0,source_gaps bigint NOT NULL DEFAULT 0,watch_errors bigint NOT NULL DEFAULT 0,journal_resets bigint NOT NULL DEFAULT 0,etw_lost_events bigint NOT NULL DEFAULT 0,falco_lost_events bigint NOT NULL DEFAULT 0,hash_failures bigint NOT NULL DEFAULT 0,signature_failures bigint NOT NULL DEFAULT 0,last_upload_result text NOT NULL,policy_version text NOT NULL,last_sequence bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,endpoint_id));
CREATE TABLE platform.file_policy_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES platform.tenants(id),name text NOT NULL,version integer NOT NULL,policy jsonb NOT NULL,sha256 text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by text NOT NULL,UNIQUE(tenant_id,name,version));
CREATE TABLE platform.file_policy_assignments(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid,policy_id uuid NOT NULL REFERENCES platform.file_policy_versions(id),assigned_at timestamptz NOT NULL DEFAULT now(),assigned_by text NOT NULL,UNIQUE NULLS NOT DISTINCT(tenant_id,endpoint_id));
CREATE TABLE platform.file_policy_acknowledgements(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),endpoint_id uuid NOT NULL,policy_id uuid NOT NULL,version integer NOT NULL,applied boolean NOT NULL,validation_error text,acknowledged_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,endpoint_id));
COMMIT;
